          Xpp3Dom itemNode = new Xpp3Dom(childKey);
          if (item instanceof Map)
            //noinspection unchecked
            toDom(itemNode, (Map) item);
          else
            itemNode.setValue(item.toString());
          parent.addChild(itemNode);
        }
